CREATE OR REPLACE FUNCTION public.can_call_member(_other uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND _other IS NOT NULL AND auth.uid()<>_other AND public.account_allowed(auth.uid()) AND public.account_allowed(_other) AND public.has_paid_bell(auth.uid()) AND public.has_paid_bell(_other) AND (public.can_post_chat(NULL,_other) OR EXISTS(SELECT 1 FROM public.messages WHERE (sender_id=auth.uid() AND receiver_id=_other) OR (sender_id=_other AND receiver_id=auth.uid()))) $$;
REVOKE ALL ON FUNCTION public.can_call_member(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_call_member(uuid) TO authenticated,service_role;
CREATE TABLE public.app_calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),caller_id uuid NOT NULL,callee_id uuid NOT NULL,video boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
GRANT SELECT ON public.app_calls TO authenticated; GRANT ALL ON public.app_calls TO service_role;
ALTER TABLE public.app_calls ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_call_read ON public.app_calls FOR SELECT TO authenticated USING(auth.uid() IN(caller_id,callee_id));
CREATE TABLE public.app_call_signals(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,call_id uuid NOT NULL REFERENCES public.app_calls(id) ON DELETE CASCADE,sender_id uuid NOT NULL,receiver_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('offer','answer','ice','end')),payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.app_call_signals TO authenticated; GRANT ALL ON public.app_call_signals TO service_role; GRANT USAGE,SELECT ON SEQUENCE public.app_call_signals_id_seq TO service_role;
ALTER TABLE public.app_call_signals ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_signal_read ON public.app_call_signals FOR SELECT TO authenticated USING(receiver_id=auth.uid() AND created_at>now()-interval '2 minutes' AND (kind='end' OR public.can_call_member(sender_id)));
CREATE INDEX app_call_inbox_idx ON public.app_call_signals(receiver_id,id);
CREATE OR REPLACE FUNCTION public.begin_app_call(_other uuid,_video boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; BEGIN IF NOT public.can_call_member(_other) THEN RAISE EXCEPTION 'BOTH_PAID_REQUIRED'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(least(auth.uid(),_other)::text,123)); PERFORM pg_advisory_xact_lock(hashtextextended(greatest(auth.uid(),_other)::text,123)); IF EXISTS(SELECT 1 FROM public.app_calls WHERE ended_at IS NULL AND created_at>now()-interval '2 minutes' AND (caller_id IN(auth.uid(),_other) OR callee_id IN(auth.uid(),_other))) THEN RAISE EXCEPTION 'CALL_BUSY'; END IF; DELETE FROM public.app_calls WHERE created_at<now()-interval '1 day' AND auth.uid() IN(caller_id,callee_id); INSERT INTO public.app_calls(caller_id,callee_id,video) VALUES(auth.uid(),_other,_video) RETURNING id INTO cid; RETURN cid; END $$;
CREATE OR REPLACE FUNCTION public.send_app_call_signal(_call uuid,_kind text,_payload jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.app_calls; target uuid; BEGIN SELECT * INTO c FROM public.app_calls WHERE id=_call FOR UPDATE; IF c.id IS NULL OR auth.uid() IS NULL OR auth.uid() NOT IN(c.caller_id,c.callee_id) THEN RAISE EXCEPTION 'CALL_PARTICIPANT_REQUIRED'; END IF; target:=CASE WHEN auth.uid()=c.caller_id THEN c.callee_id ELSE c.caller_id END; IF _kind NOT IN('offer','answer','ice','end') OR octet_length(_payload::text)>65536 THEN RAISE EXCEPTION 'INVALID_SIGNAL'; END IF; IF _kind<>'end' AND (c.ended_at IS NOT NULL OR c.created_at<now()-interval '2 hours' OR NOT public.can_call_member(target)) THEN RAISE EXCEPTION 'BOTH_PAID_REQUIRED'; END IF; IF (_kind='offer' AND auth.uid()<>c.caller_id) OR (_kind='answer' AND auth.uid()<>c.callee_id) THEN RAISE EXCEPTION 'INVALID_SIGNAL_SENDER'; END IF; IF _kind='end' THEN UPDATE public.app_calls SET ended_at=coalesce(ended_at,now()) WHERE id=c.id; END IF; INSERT INTO public.app_call_signals(call_id,sender_id,receiver_id,kind,payload) VALUES(c.id,auth.uid(),target,_kind,coalesce(_payload,'{}'::jsonb)); END $$;
CREATE OR REPLACE FUNCTION public.app_call_dial_number(_other uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ph text; BEGIN IF NOT public.can_call_member(_other) THEN RAISE EXCEPTION 'BOTH_PAID_REQUIRED'; END IF; SELECT chat_phone INTO ph FROM public.messages WHERE sender_id=_other AND receiver_id=auth.uid() AND chat_phone ~ '^[6-9][0-9]{9}$' ORDER BY created_at DESC LIMIT 1; RETURN ph; END $$;
REVOKE ALL ON FUNCTION public.begin_app_call(uuid,boolean),public.send_app_call_signal(uuid,text,jsonb),public.app_call_dial_number(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.begin_app_call(uuid,boolean),public.send_app_call_signal(uuid,text,jsonb),public.app_call_dial_number(uuid) TO authenticated,service_role;